const decode = (b64: string, stride: number, min: number[], max: number[]): Float32Array => {
  const raw = typeof atob === 'function'
    ? Uint8Array.from(atob(b64), c => c.charCodeAt(0))
    : Uint8Array.from(Buffer.from(b64, 'base64'))
  const q = new Int16Array(raw.buffer, raw.byteOffset, raw.byteLength / 2)
  const out = new Float32Array(q.length)
  for (let i = 0; i < q.length; i += stride) {
    for (let k = 0; k < stride; k++) out[i + k] = min[k] + ((q[i + k] + 32768) / 65535) * (max[k] - min[k])
  }
  return out
}

